head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.gDepCd;
scwin.clickBzProcsNo = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF07070.xml";
//수정요청 창에 넘겨주기 위한 변수
scwin.clickListInvstgBzTpCd = "150";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //보호예수인출


scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "PRTDEPO_NO"); //보호예수인출 업무처리번호
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);
    clickListProcsStatCd = dts_List.getCellData(eval(obj), "LIST_PROCS_STAT_CD");
};
scwin.fn_list_sync = function() {
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRTDEPOWITHD_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prtdepowithd.list.select" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 회사코드
        "&{P}param02=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 회사코드
        "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + // 일자
        "&{P}param04=" + $c.stf.getObjectValue(edt_EDate) + // 일자
        "&{P}param05=" + vMarketTpCd + // 시장구분
        "&{P}param06=" + vMarketTpCd; // 일자

    //"&{P}param09=" + getObjectValue(rdo_APPROV_YN) + // 상태
    // "&{P}param10=" + getObjectValue(rdo_APPROV_YN); // 상태

    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};



/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "의무보유주식의 처분 목록", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



//상세보기 및 접수, 반려, 인출승인등...
scwin.fn_Detail = async function(vBzProcsNo) {
    //수정요청 리스트 팝업창
    if ("34" == clickListProcsStatCd) {
        //수정요청 리스트 팝업창
        var adjreqUrl = "/lstinvstg/ULDSTF07090.gfm";
        await $c.frame.CreateDialogFrame("ULDSTF07090.gfm", adjreqUrl, "의무보유주식의 처분 수정요청 리스트", 50, 50, 960, 280, "window");
    } else {
        var url = "/lstinvstg/ULDSTF07071.gfm?BZ_PROCS_NO=" + vBzProcsNo;
        await $c.frame.CreateDialogFrame("DLG_PDW", url, "의무보유주식의 처분 관리", 100, 100, 710, 390, "window");
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_setBzProcsNo(row);
    vBzProcsNo = scwin.clickBzProcsNo;
    scwin.fn_Detail(vBzProcsNo);
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_mkt_gubun, false);
        $c.cm.setColumnProp(grd_List, "MKT_NM", "Show", false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue("20111201");
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
